def generate():
    existing = bc.get_existing_names_for_theme('Mitologia & Lendas')
    print(f"Existing Mitologia items count: {len(existing)}")
    
    # Check how many from RAW_ITEMS are new
    seen = set()
    new_items = []
    for item in RAW_ITEMS:
        name = item[0]
        norm = bc.normalize_name(name)
        if norm not in existing and norm not in seen:
            seen.add(norm)
            new_items.append(item)
        else:
            print(f"Duplicate or already existing: {name}")
            
    print(f"grega_romana candidates new: {len(new_items)}")

if __name__ == '__main__':
    generate()
